function HUD.prototype.rectVerts(self, x, y, w, h)
    return {
        Vec2(x, y),
        Vec2(x + w, y),
        Vec2(x + w, y + h),
        Vec2(x, y + h)
    }
end
function HUD.prototype.screenVerts(self, w, h)
    return self:rectVerts(-w / 2, -h / 2, w, h)
end
function HUD.prototype.circle(self, draw, cx, cy, r, segs, width, color, from, sweep)
    do
        local i = 0
        while i < segs do
            local a0 = from + i / segs * sweep
            local a1 = from + (i + 1) / segs * sweep
            draw:drawSegment(
                Vec2(
                    cx + math.cos(a0) * r,
                    cy + math.sin(a0) * r
                ),
                Vec2(
                    cx + math.cos(a1) * r,
                    cy + math.sin(a1) * r
                ),
                width,
                col(color)
            )
            i = i + 1
        end
    end
end
function HUD.prototype.diamond(self, draw, x, y, s, fill, bw, border)
    draw:drawPolygon(
        {
            Vec2(x, y + s),
            Vec2(x + s, y),
            Vec2(x, y - s),
            Vec2(x - s, y)
        },
        col(fill),
        bw,
        col(border)
    )
end
function HUD.prototype.updatePixelLife(self, st, x0, rowY)
    if self.heartTex == nil or self.barFrameSp == nil or self.barFillSp == nil then
        return false
    end
    local bottomY = rowY - 24
    local barX = x0 + 3 * HEART_STEP + 16
    local ratio = st.maxLife > 0 and math.max(
        0,
        math.min(1, st.heroineLife / st.maxLife)
    ) or 0
    do
        local i = 0
        while i < #self.heartSps do
            local sp = self.heartSps[i + 1]
            local active = i < st.maxLife
            sp.visible = active
            if active then
                sp.position = Vec2(x0 + i * HEART_STEP, bottomY)
                sp.color = i < st.heroineLife and Color(255, 255, 255, 255) or Color(255, 255, 255, 70)
            end
            i = i + 1
        end
    end
    if self.barFrameSp ~= nil then
        self.barFrameSp.visible = true
        self.barFrameSp.position = Vec2(barX, bottomY)
    end
    if self.barFillSp ~= nil then
        local rw = math.floor(16 * ratio + 0.5)
        self.barFillSp.visible = rw > 0
        if rw > 0 then
            self.barFillSp.textureRect = Rect(0, 0, rw, 10)
            self.barFillSp.position = Vec2(barX + FILL_PAD_X, bottomY + FILL_PAD_Y)
        end
    end
    return true
end
function HUD.prototype.drawTitleBg(self, w, h)
    self.titleBg:clear()
    self.titleBg:drawPolygon(
        self:screenVerts(w, h),
        Palette.paper
    )
    local mx = w / 2 - 190
    local my = h / 2 - 170
    self:circle(
        self.titleBg,
        mx,
        my,
        96,
        40,
        2,
        Palette.goldSoft,
        0,
        math.pi * 2
    )
    self.titleBg:drawDot(
        Vec2(mx, my),
        84,
        col(Palette.moonWhite)
    )
    do
        local i = 0
        while i < 4 do
            local x0 = -w / 2 + i * (w / 3.2)
            self.titleBg:drawSegment(
                Vec2(x0, -h / 2 + 40 + i * 14),
                Vec2(x0 + w / 3.6, -h / 2 + 26 + i * 14),
                26 + i * 8,
                col(Palette.paleInkFar)
            )
            i = i + 1
        end
    end
end
function HUD.prototype.drawPauseBg(self, w, h)
    self.pauseBg:clear()
    self.pauseBg:drawPolygon(
        self:screenVerts(w, h),
        col(Palette.inkWash)
    )
    self.pauseBg:drawPolygon(
        self:rectVerts(-320, -220, 640, 440),
        col(Palette.paper),
        2,
        col(Palette.inkDark)
    )
    self.pauseBg:drawPolygon(
        self:rectVerts(-308, -208, 616, 416),
        col(NO_FILL),
        1,
        col(Palette.goldSoft)
    )
end
function HUD.prototype.flashDamage(self)
    self.flashTimer = FLASH_TIME
end
function HUD.prototype.setRewind(self, v)
    self.rewindV = v
    if self.rewindLb ~= nil then
        self.rewindLb.visible = v >= 0
    end
end
