    end
    local w = View.size.width
    local h = View.size.height
    self.endingBg:clear()
    self.endingBg:drawPolygon(
        self:screenVerts(w, h),
        col(ink(Palette.paper.r, Palette.paper.g, Palette.paper.b, 242))
    )
    self.endingBg:drawPolygon(
        self:rectVerts(-w / 2 + 14, -h / 2 + 14, w - 28, h - 28),
        col(NO_FILL),
        1,
        col(Palette.goldSoft)
    )
    setText(self.endingTitleLb, e.title)
    do
        local i = 0
        while i < #self.endingLineLbs do
            setText(self.endingLineLbs[i + 1], i < #e.lines and e.lines[i + 1] or "")
            i = i + 1
        end
    end
    self.endingNode.visible = true
end
function HUD.prototype.hideEnding(self)
    self.endingNode.visible = false
end
function HUD.prototype.setTitleVisible(self, v)
    self.titleNode.visible = v
end
function HUD.prototype.setPauseVisible(self, v)
    self.pauseNode.visible = v
end
function HUD.prototype.update(self, dt, args)
    local st = args.state
    local w = View.size.width
    local h = View.size.height
    local top = h / 2
    self.hud:clear()
    local baseX = -w / 2 + 44
    local rowY = top - 44
    local pxLife = self:updatePixelLife(st, baseX - 4, rowY)
    if not pxLife then
        do
            local i = 0
            while i < st.maxLife do
                local x = baseX + i * 30
                if i < st.heroineLife then
                    self:diamond(
                        self.hud,
                        x,
                        rowY,
                        12,
                        Palette.vermilion,
                        2,
                        Palette.inkDark
                    )
                else
                    self:diamond(
                        self.hud,
                        x,
                        rowY,
                        12,
                        NO_FILL,
                        2,
                        Palette.inkFaint
                    )
                end
                i = i + 1
            end
        end
    end
    local ix0 = pxLife and baseX - 4 + 3 * HEART_STEP + 16 + 64 * BAR_SCALE + 16 or baseX + st.maxLife * 30 + 26
    do
        local i = 0
        while i < st.maxSwordIntent do
            local x = ix0 + i * 16
            if i < st.swordIntent then
                self.hud:drawSegment(
                    Vec2(x, rowY - 10),
                    Vec2(x, rowY + 10),
                    4,
                    col(Palette.moonCyan)
                )
            else
                self.hud:drawSegment(
                    Vec2(x, rowY - 10),
                    Vec2(x, rowY + 10),
                    2,
                    col(Palette.inkFaint)
                )
            end
            i = i + 1
        end
    end
    local cx = w / 2 - 74
    local cy = top - 40
    self:circle(
        self.hud,
        cx,
        cy,
        22,
        28,
        2,
        Palette.gold,
        0,
        math.pi * 2
    )
    local phase = st.phaseIndex
    local illum = (1 - math.cos(phase / 8 * math.pi * 2)) / 2
    if phase == 0 then
        self.hud:drawDot(
            Vec2(cx, cy),
            9,
            col(Palette.inkWash)
        )
    else
        self.hud:drawDot(
            Vec2(cx, cy),
            5 + 12 * illum,
            col(Palette.moonWhite)
        )
        self.hud:drawDot(
            Vec2(cx + (phase < 4 and 12 or -12), cy),
            3,
            col(Palette.goldSoft)
        )
    end
    setText(self.phaseLb, phase >= 0 and phase < #PHASE_NAMES and PHASE_NAMES[phase + 1] or "")
    setText(
        self.loopLb,
        ("第" .. tostring(st.loopIndex + 1)) .. "周目"
    )
    local trust = st.shenyanTrust
    setText(
        self.trustLb,
        ("砚·信任 " .. tostring(trust)) .. " / 4"
    )
    if self.trustLb ~= nil then
        self.trustLb.color = trust >= 4 and Color(Palette.moonCyan.r, Palette.moonCyan.g, Palette.moonCyan.b, 255) or Color(Palette.paleInk.r, Palette.paleInk.g, Palette.paleInk.b, 255)
    end
    setText(self.objectiveLb, args.objective)
    setText(self.hintLb, args.hint)
    local boss = args.boss
    if boss ~= nil and not boss.dead and boss.maxHp > 0 then
        local bw = 520
        local bx = -bw / 2
        local by = -h / 2 + 66
        self.hud:drawPolygon(
            self:rectVerts(bx, by, bw, 12),
            col(NO_FILL),
            2,
            col(Palette.inkDark)
        )
        local frac = math.max(
            0,
            math.min(1, boss.hp / boss.maxHp)
        )
        if frac > 0 then
            self.hud:drawPolygon(
                self:rectVerts(bx + 2, by + 2, (bw - 4) * frac, 8),
                col(Palette.vermilion)
            )
        end
    end
    self.flash:clear()
    if self.flashTimer > 0 then
        self.flashTimer = math.max(0, self.flashTimer - dt)
        local a = math.floor(255 * 0.35 * (self.flashTimer / FLASH_TIME))
        self.flash:drawPolygon(
            self:screenVerts(w, h),
            col(ink(Palette.vermilion.r, Palette.vermilion.g, Palette.vermilion.b, a))
        )
    end
    self.rewindDraw:clear()
    if self.rewindV >= 0 then
        local v = math.max(
            0,
            math.min(1, self.rewindV)
        )
        self.rewindDraw:drawPolygon(
            self:screenVerts(w, h),
            col(Palette.mist)
        )
        self:circle(
            self.rewindDraw,
            0,
            0,
            46,
            36,
            4,
            Palette.moonCyan,
            -math.pi / 2,
            v * math.pi * 2
        )
    end
    if self.titleNode.visible and self.titleStartLb ~= nil then
        local a = 150 + math.floor(100 * math.sin(args.time * 2.6))
        self.titleStartLb.color = Color(Palette.inkSoft.r, Palette.inkSoft.g, Palette.inkSoft.b, a)
    end
end
return ____exports
